package com.teamwizardry.wizardry.api.capability.chunk;

import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;

import com.teamwizardry.wizardry.api.block.TileCachable;

import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraftforge.common.capabilities.Capability;

public class StandardWizardryChunk implements WizardryChunk
{
	private Set<TileCachable> cachedTiles = Collections.newSetFromMap(new WeakHashMap<TileCachable, Boolean>());

	public static StandardWizardryChunk create()
	{
		return new StandardWizardryChunk();
	}


	@Override
	public boolean hasCapability(Capability<?> capability, EnumFacing facing)
	{
		return capability == WizardryChunkCapability.capability();
	}

	@Override
	public <T> T getCapability(Capability<T> capability, EnumFacing facing)
	{
		return capability == WizardryChunkCapability.capability() ? WizardryChunkCapability.capability().cast(this) : null;
	}

	@Override
	public NBTTagCompound serializeNBT()
	{
		return new NBTTagCompound();
	}

	@Override
	public void deserializeNBT(NBTTagCompound nbt){}

	@Override
	public void addCachableTile(TileCachable tile)
	{
		cachedTiles.add(tile);
	}

	@Override
	public Set<TileCachable> getCachableTiles()
	{
		return cachedTiles;
	}

}

package com.teamwizardry.wizardry.api.capability.world;

import com.teamwizardry.librarianlib.features.network.PacketHandler;
import com.teamwizardry.wizardry.api.SpellObjectManager;
import com.teamwizardry.wizardry.common.core.nemez.NemezTracker;
import com.teamwizardry.wizardry.common.network.capability.PacketSyncWizardryWorld;
import net.minecraft.nbt.NBTBase;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.util.Constants;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public class StandardWizardryWorld implements WizardryWorld {
	private World world;
	private SpellObjectManager spellObjectManager = new SpellObjectManager();
	public HashMap<BlockPos, NemezTracker> blockNemezDrives = new HashMap<>();
	public HashMap<UUID, NemezTracker> entityNemezDrives = new HashMap<>();
	public HashMap<UUID, Integer> zombieBackupTracker = new HashMap<>();

	public static StandardWizardryWorld create(World world) {
		StandardWizardryWorld wizardryWorld = new StandardWizardryWorld();
		wizardryWorld.world = world;
		return wizardryWorld;
	}

	public static StandardWizardryWorld create() {
		return new StandardWizardryWorld();
	}

	//		PacketHandler.NETWORK.sendToDimension(new PacketSyncWizardryWorld(serializeNBT()), world.provider.getDimension());
	@Override
	public SpellObjectManager getSpellObjectManager() {
		return spellObjectManager;
	}

	@Override
	public NemezTracker addNemezDrive(BlockPos pos, NemezTracker nemezDrive) {
		blockNemezDrives.put(pos, nemezDrive);

		PacketHandler.NETWORK.sendToDimension(new PacketSyncWizardryWorld(serializeNBT()), world.provider.getDimension());

		return nemezDrive;
	}

	@Override
	public NemezTracker addNemezDrive(UUID uuid, NemezTracker nemezDrive) {
		entityNemezDrives.put(uuid, nemezDrive);

		PacketHandler.NETWORK.sendToDimension(new PacketSyncWizardryWorld(serializeNBT()), world.provider.getDimension());

		return nemezDrive;
	}

	@Override
	public void removeNemezDrive(BlockPos pos) {
		blockNemezDrives.remove(pos);

		PacketHandler.NETWORK.sendToDimension(new PacketSyncWizardryWorld(serializeNBT()), world.provider.getDimension());
	}

	@Override
	public void removeNemezDrive(UUID uuid) {
		entityNemezDrives.remove(uuid);

		PacketHandler.NETWORK.sendToDimension(new PacketSyncWizardryWorld(serializeNBT()), world.provider.getDimension());
	}

	@Override
	public HashMap<BlockPos, NemezTracker> getBlockNemezDrives() {
		return blockNemezDrives;
	}

	@Override
	public HashMap<UUID, NemezTracker> getEntityNemezDrives() {
		return entityNemezDrives;
	}

	@Override
	public int getBackupCount(UUID player) {
		if(!zombieBackupTracker.containsKey(player)) {
			zombieBackupTracker.put(player, 0);
		}

		return zombieBackupTracker.get(player);
	}

	@Override
	public void setBackupCount(UUID player, int count) {
		zombieBackupTracker.put(player, count);
	}

	@Override
	public void incBackupCount(UUID player) {
		if(!zombieBackupTracker.containsKey(player)) {
			zombieBackupTracker.put(player, 0);
		}

		zombieBackupTracker.put(player, getBackupCount(player)+1);
	}

	@Override
	public void decBackupCount(UUID player) {
		if(!zombieBackupTracker.containsKey(player)) {
			zombieBackupTracker.put(player, 0);
		}

		zombieBackupTracker.put(player, Math.max(0, getBackupCount(player)-1));
	}

	@Override
	public HashMap<UUID, Integer> getBackupMap() {
		return zombieBackupTracker;
	}

	@Override
	public void setBackupMap(HashMap<UUID, Integer> map) {
		zombieBackupTracker = map;
	}


	@Override
	public NBTTagCompound serializeNBT() {
		NBTTagCompound compound = new NBTTagCompound();

		compound.setTag("spell_object_manager", spellObjectManager.manager.toNbt());

		NBTTagList driveNBT = new NBTTagList();
		for (Map.Entry<BlockPos, NemezTracker> entry : blockNemezDrives.entrySet()) {
			if (entry == null) continue;
			NBTTagCompound compound1 = new NBTTagCompound();
			compound1.setLong("pos", entry.getKey().toLong());
			compound1.setTag("drive", entry.getValue().serializeNBT());
			driveNBT.appendTag(compound1);
		}

		compound.setTag("drives", driveNBT);
		return compound;
	}

	@Override
	public void deserializeNBT(NBTTagCompound compound) {
		if (compound.hasKey("spell_object_manager")) {
			spellObjectManager = new SpellObjectManager();
			spellObjectManager.manager.fromNbt(compound.getCompoundTag("spell_object_manager"));
		}

		if (compound.hasKey("drives")) {
			NBTTagList driveNBT = compound.getTagList("drives", Constants.NBT.TAG_COMPOUND);
			for (NBTBase base : driveNBT) {
				if (base instanceof NBTTagCompound) {
					if (((NBTTagCompound) base).hasKey("pos") && ((NBTTagCompound) base).hasKey("drive")) {
						BlockPos pos = BlockPos.fromLong(((NBTTagCompound) base).getLong("pos"));
						NemezTracker tracker = new NemezTracker();
						tracker.deserializeNBT(((NBTTagCompound) base).getTagList("drive", Constants.NBT.TAG_COMPOUND));

						blockNemezDrives.put(pos, tracker);
					}
				}
			}
		}
	}

	@Override
	public boolean hasCapability(@Nonnull Capability<?> capability, @Nullable EnumFacing facing) {
		return capability == WizardryWorldCapability.capability();
	}

	@Nullable
	@Override
	public <T> T getCapability(@Nonnull Capability<T> capability, @Nullable EnumFacing facing) {
		return capability == WizardryWorldCapability.capability() ? WizardryWorldCapability.capability().cast(this) : null;
	}
}

package com.teamwizardry.wizardry.api.capability.world;

import com.teamwizardry.wizardry.Wizardry;
import net.minecraft.nbt.NBTBase;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.ResourceLocation;
import net.minecraft.world.World;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityInject;
import net.minecraftforge.common.capabilities.CapabilityManager;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;

import java.util.Objects;

@Mod.EventBusSubscriber(modid = Wizardry.MODID)
public final class WizardryWorldCapability {
	private static final ResourceLocation WIZARDRY_WORLD_ID = new ResourceLocation(Wizardry.MODID, "wizardry_world");
	@CapabilityInject(WizardryWorld.class)
	private static final Capability<WizardryWorld> CAPABILITY = null;

	private WizardryWorldCapability() {
	}

	public static Capability<WizardryWorld> capability() {
		//noinspection ConstantConditions
		return Objects.requireNonNull(CAPABILITY, "MANA_CAPABILITY");
	}

	// call in preinit
	public static void init() {
		CapabilityManager.INSTANCE.register(WizardryWorld.class, new WizardryWorldStorage(), StandardWizardryWorld::create);
	}

	public static WizardryWorld get(World world) {
		WizardryWorld cap = world.getCapability(capability(), null);
		if (cap == null) {
			throw new IllegalStateException("Missing capability: " + world.getWorldInfo().getWorldName() + "/" + world.provider.getDimensionType().getName());
		}
		return cap;
	}

	@SubscribeEvent
	public static void onAttachCapabilities(AttachCapabilitiesEvent<World> event) {
		event.addCapability(WIZARDRY_WORLD_ID, StandardWizardryWorld.create(event.getObject()));
	}

	// other event subscriptions related to cap behavior

	private static final class WizardryWorldStorage implements Capability.IStorage<WizardryWorld> {
		@Override
		public NBTBase writeNBT(Capability<WizardryWorld> capability, WizardryWorld world, EnumFacing side) {
			return world.serializeNBT();
		}

		@Override
		public void readNBT(Capability<WizardryWorld> capability, WizardryWorld world, EnumFacing side, NBTBase nbt) {
			if (nbt instanceof NBTTagCompound) {
				world.deserializeNBT((NBTTagCompound) nbt);
			}
		}
	}
}

package com.teamwizardry.wizardry.api.capability.world;

import net.minecraft.nbt.NBTBase;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraftforge.common.capabilities.Capability;

import javax.annotation.Nullable;
import java.util.HashMap;
import java.util.UUID;

/**
 * Project: Wizardry
 * Created by Carbon
 * Copyright (c) Carbon 2020
 */
public class WizardryWorldStorage implements Capability.IStorage<WizardryWorld> {
	public static final WizardryWorldStorage INSTANCE = new WizardryWorldStorage();
	public static final String BACKUP_NBT_TAG = "zombieBackup";

	@Nullable
	@Override
	public NBTBase writeNBT(Capability<WizardryWorld> capability, WizardryWorld instance, EnumFacing side) {
		NBTTagCompound playerMap = new NBTTagCompound();

		for(UUID playerId : instance.getBackupMap().keySet()) {
			playerMap.setInteger(playerId.toString(), instance.getBackupMap().get(playerId));
		}

		NBTTagCompound nbt = new NBTTagCompound();
		nbt.setTag(BACKUP_NBT_TAG, playerMap);

		return nbt;
	}

	@Override
	public void readNBT(Capability<WizardryWorld> capability, WizardryWorld instance, EnumFacing side, NBTBase nbt) {
		HashMap<UUID, Integer> map = new HashMap<>();
		NBTTagCompound tag = (NBTTagCompound) nbt;
		NBTTagCompound playerBackup = tag.getCompoundTag(BACKUP_NBT_TAG);

		for(String playerId : playerBackup.getKeySet()) {
			map.put(UUID.fromString(playerId), playerBackup.getInteger(playerId));
		}

		instance.setBackupMap(map);
	}
}

package com.teamwizardry.wizardry.api.item.halo;

import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.util.math.Vec3d;
import net.minecraft.world.World;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

import javax.annotation.Nonnull;
import java.util.function.BiConsumer;

public class HaloInfusionItem {

	private final ItemStack stack;
	private final String nbtName;

	public HaloInfusionItem(ItemStack stack) {
		this.stack = stack;
		this.nbtName = stack.getTranslationKey();
	}

	public HaloInfusionItem(Item item) {
		this(item, 1);
	}

	public HaloInfusionItem(Item item, int count) {
		this(new ItemStack(item, count));
	}

	public ItemStack getStack() {
		return stack;
	}

	public String getNbtName() {
		return nbtName;
	}

	@SideOnly(Side.CLIENT)
	public BiConsumer<Vec3d, World> getRenderer() {
		return HaloInfusionItemRenderers.getHaloRenderer(this);
	}

	@Nonnull
	public static HaloInfusionItem deserialize(String nbtName) {
		for (HaloInfusionItem haloInfusionItem : HaloInfusionItemRegistry.getItems()) {
			if (haloInfusionItem.getNbtName().equalsIgnoreCase(nbtName)) {
				return haloInfusionItem;
			}
		}
		return HaloInfusionItemRegistry.EMPTY;
	}

	@SideOnly(Side.CLIENT)
	public void render(World world, Vec3d pos) {
		getRenderer().accept(pos, world);
	}
}

package com.teamwizardry.wizardry.api.item.halo;

import com.teamwizardry.wizardry.init.ModItems;
import net.minecraft.init.Items;
import net.minecraft.item.ItemStack;

import java.util.ArrayList;
import java.util.List;

public final class HaloInfusionItemRegistry {

	public static HaloInfusionItemRegistry INSTANCE = new HaloInfusionItemRegistry();

	public static final HaloInfusionItem EMPTY;
	public static final HaloInfusionItem OVERWORLD_RABBIT_FOOT;
	public static final HaloInfusionItem OVERWORLD_PRISMARINE_CRYSTALS;
	public static final HaloInfusionItem OVERWORLD_EMERALD;
	public static final HaloInfusionItem NETHER_BLAZE_POWDERS;
	public static final HaloInfusionItem NETHER_GHAST_TEARS;
	public static final HaloInfusionItem NETHER_NETHER_STAR;
	public static final HaloInfusionItem END_POPPED_CHORUS;
	public static final HaloInfusionItem END_DRAGON_BREATH;
	public static final HaloInfusionItem END_SHULKER_SHELL;
	public static final HaloInfusionItem UNDERWORLD_FAIRY_DUST;
	public static final HaloInfusionItem UNDEROWRLD_UNICORN_HORN;
	private static final List<HaloInfusionItem> items = new ArrayList<>();

	static {
		addHaloInfusionItem(EMPTY = new HaloInfusionItem(ItemStack.EMPTY));

		addHaloInfusionItem(OVERWORLD_RABBIT_FOOT = new HaloInfusionItem(Items.RABBIT_FOOT, 2));
		addHaloInfusionItem(OVERWORLD_PRISMARINE_CRYSTALS = new HaloInfusionItem(Items.PRISMARINE_CRYSTALS, 4));
		addHaloInfusionItem(OVERWORLD_EMERALD = new HaloInfusionItem(Items.EMERALD));

		addHaloInfusionItem(NETHER_BLAZE_POWDERS = new HaloInfusionItem(Items.BLAZE_POWDER, 5));
		addHaloInfusionItem(NETHER_GHAST_TEARS = new HaloInfusionItem(Items.GHAST_TEAR, 4));
		addHaloInfusionItem(NETHER_NETHER_STAR = new HaloInfusionItem(Items.NETHER_STAR));

		addHaloInfusionItem(END_POPPED_CHORUS = new HaloInfusionItem(Items.CHORUS_FRUIT_POPPED));
		addHaloInfusionItem(END_DRAGON_BREATH = new HaloInfusionItem(Items.DRAGON_BREATH));
		addHaloInfusionItem(END_SHULKER_SHELL = new HaloInfusionItem(Items.SHULKER_SHELL));

		addHaloInfusionItem(UNDERWORLD_FAIRY_DUST = new HaloInfusionItem(ModItems.FAIRY_DUST));
		addHaloInfusionItem(UNDEROWRLD_UNICORN_HORN = new HaloInfusionItem(ModItems.UNICORN_HORN));
	}

	public static void addHaloInfusionItem(HaloInfusionItem item) {
		items.add(item);
	}

	public static List<HaloInfusionItem> getItems() {
		return items;
	}

	public static HaloInfusionItem getInfusionItemFromStack(ItemStack stack) {
		if (stack.isEmpty()) return EMPTY;
		for (HaloInfusionItem item : items) {
			if (ItemStack.areItemStacksEqual(stack, item.getStack())) return item;
		}
		return EMPTY;
	}

	public static boolean isHaloInfusionItem(ItemStack stack) {
		if (stack.isEmpty()) return false;
		for (HaloInfusionItem item : items) {
			if (ItemStack.areItemStacksEqual(stack, item.getStack())) return true;
		}
		return false;
	}

	public static HaloInfusionItem getItemFromName(String nbtName) {
		for (HaloInfusionItem item : items) {
			if (item.getNbtName().equals(nbtName)) return item;
		}
		return HaloInfusionItemRegistry.EMPTY;
	}
}

package com.teamwizardry.wizardry.common.core;

import com.teamwizardry.wizardry.api.capability.world.WizardryWorld;
import com.teamwizardry.wizardry.api.capability.world.WizardryWorldCapability;
import com.teamwizardry.wizardry.common.core.nemez.NemezTracker;
import net.minecraft.entity.Entity;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;

import javax.annotation.Nullable;
import java.util.HashMap;
import java.util.UUID;

public class WizardryNemezManager {

	public static NemezTracker getOrCreateNemezDrive(World world, BlockPos pos) {
		WizardryWorld worldCap = WizardryWorldCapability.get(world);
		HashMap<BlockPos, NemezTracker> nemezDrives = worldCap.getBlockNemezDrives();

		if (nemezDrives.containsKey(pos)) return nemezDrives.get(pos);

		return worldCap.addNemezDrive(pos, new NemezTracker());
	}

	public static NemezTracker getOrCreateNemezDrive(World world, Entity entity) {
		WizardryWorld worldCap = WizardryWorldCapability.get(world);
		HashMap<UUID, NemezTracker> nemezDrives = worldCap.getEntityNemezDrives();

		if (nemezDrives.containsKey(entity.getUniqueID())) return nemezDrives.get(entity.getUniqueID());

		return worldCap.addNemezDrive(entity.getUniqueID(), new NemezTracker());
	}

	public static NemezTracker getOrCreateNemezDrive(World world, UUID uuid) {
		WizardryWorld worldCap = WizardryWorldCapability.get(world);
		HashMap<UUID, NemezTracker> nemezDrives = worldCap.getEntityNemezDrives();

		if (nemezDrives.containsKey(uuid)) return nemezDrives.get(uuid);

		return worldCap.addNemezDrive(uuid, new NemezTracker());
	}

	@Nullable
	public static NemezTracker getAndRemoveNemezDrive(World world, BlockPos pos) {
		WizardryWorld worldCap = WizardryWorldCapability.get(world);

		if (worldCap.getBlockNemezDrives().containsKey(pos)) {
			NemezTracker tracker = worldCap.getBlockNemezDrives().get(pos);
			worldCap.removeNemezDrive(pos);
			return tracker;
		}
		return null;
	}

	@Nullable
	public static NemezTracker getAndRemoveNemezDrive(World world, Entity entity) {
		WizardryWorld worldCap = WizardryWorldCapability.get(world);

		if (worldCap.getEntityNemezDrives().containsKey(entity.getUniqueID())) {
			NemezTracker tracker = worldCap.getEntityNemezDrives().get(entity.getUniqueID());
			worldCap.removeNemezDrive(entity.getUniqueID());
			return tracker;
		}
		return null;
	}

	@Nullable
	public static NemezTracker getAndRemoveNemezDrive(World world, UUID uuid) {
		WizardryWorld worldCap = WizardryWorldCapability.get(world);

		if (worldCap.getEntityNemezDrives().containsKey(uuid)) {
			NemezTracker tracker = worldCap.getEntityNemezDrives().get(uuid);
			worldCap.removeNemezDrive(uuid);
			return tracker;
		}
		return null;
	}
}

package com.teamwizardry.wizardry.common.core.nemez;

import com.google.common.collect.ArrayListMultimap;
import com.google.common.collect.ListMultimap;
import com.google.common.collect.Lists;
import net.minecraft.block.Block;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.Entity;
import net.minecraft.nbt.NBTBase;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;

import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * @author WireSegal
 * Created at 3:12 PM on 1/15/18.
 */
public final class Moment {
	// The lists produced are to be treated like stacks.
	private transient final Map<String, EntityMoment> totalDifference = new HashMap<>();
	private final ListMultimap<String, EntityMoment> entities = ArrayListMultimap.create();
	private final ListMultimap<BlockPos, IBlockState> blocks = ArrayListMultimap.create();

	@SuppressWarnings("deprecation")
	public static Moment fromNBT(NBTTagCompound nbt) {
		Moment newMoment = new Moment();
		NBTTagList blocksSerialized = nbt.getTagList("blocks", Constants.NBT.TAG_COMPOUND);
		NBTTagCompound entitiesSerialized = nbt.getCompoundTag("entities");

		Map<String, EntityMoment> newTotal = new HashMap<>();
		ListMultimap<String, EntityMoment> newEntities = ArrayListMultimap.create();
		ListMultimap<BlockPos, IBlockState> newBlocks = ArrayListMultimap.create();

		for (NBTBase blockUncast : blocksSerialized) {
			NBTTagCompound block = (NBTTagCompound) blockUncast;
			BlockPos pos = BlockPos.fromLong(block.getLong("pos"));
			NBTTagList states = block.getTagList("states", Constants.NBT.TAG_COMPOUND);
			for (NBTBase stateUncast : states) {
				NBTTagCompound state = (NBTTagCompound) stateUncast;
				Block blockAt = Block.getBlockFromName(state.getString("id"));
				if (blockAt != null) {
					int meta = state.getByte("data");
					newBlocks.put(pos, blockAt.getStateFromMeta(meta));
				}
			}
		}

		for (String key : entitiesSerialized.getKeySet()) {
			NBTTagList moments = entitiesSerialized.getTagList(key, Constants.NBT.TAG_COMPOUND);
			EntityMoment total = EntityMoment.EMPTY;
			for (NBTBase momentUncast : moments) {
				NBTTagCompound momentCompound = (NBTTagCompound) momentUncast;
				EntityMoment moment = EntityMoment.fromNBT(momentCompound);
				total = total.withOverride(moment);
				newEntities.put(key, moment);
			}
			newTotal.put(key, total);
		}

		newMoment.totalDifference.putAll(newTotal);
		newMoment.entities.putAll(newEntities);
		newMoment.blocks.putAll(newBlocks);
		for (String id : newMoment.entities.keySet())
			newMoment.capEntity(id);
		for (BlockPos pos : newMoment.blocks.keySet())
			newMoment.capBlock(pos);
		return newMoment;
	}

	public void addBlockSnapshot(BlockPos position, IBlockState newState) {
		List<IBlockState> moments = blocks.get(position);
		if (moments != null && !moments.isEmpty()) {
			if (moments.get(moments.size() - 1) != newState)
				return;
		}
		blocks.put(position, newState);

		capBlock(position);
	}

	public void addEntitySnapshot(Entity entity) {
		String uuid = entity.getCachedUniqueIdString();
		EntityMoment total = totalDifference.get(uuid);
		EntityMoment newMoment = EntityMoment.fromPreviousMoment(entity, total);
		if (total == null)
			totalDifference.put(uuid, newMoment);
		else if (!total.matches(entity))
			totalDifference.put(uuid, total.withOverride(newMoment));
		else
			return;

		entities.put(entity.getCachedUniqueIdString(), new EntityMoment(entity));

		capEntity(entity);
	}

	private void capBlock(BlockPos pos) {
		List<IBlockState> moments = blocks.get(pos);
		if (moments.size() > 5) {
			List<IBlockState> newMoments = Lists.newArrayList();
			int slice = moments.size() / 5;
			int remainder = moments.size() % 5;
			for (int i = 5; i > 0; i--)
				newMoments.add(moments.get(slice * i + (i > remainder ? 1 : 0)));

			blocks.replaceValues(pos, newMoments);
		}
	}

	private void capEntity(Entity entity) {
		capEntity(entity.getCachedUniqueIdString());
	}

	private void capEntity(String id) {
		List<EntityMoment> moments = entities.get(id);
		if (moments.size() > 5) {
			List<EntityMoment> newMoments = Lists.newArrayList();
			int slice = moments.size() / 5;
			int remainder = moments.size() % 5;
			for (int i = 5; i > 0; i--) {
				int startIndex = slice * i + (i > remainder ? 1 : 0);
				int endIndex = (slice - 1) * i;
				EntityMoment compiled = moments.get(startIndex);
				for (int subIndex = startIndex; subIndex > endIndex; subIndex--)
					compiled = compiled.withOverride(moments.get(subIndex));

				newMoments.add(compiled);
			}

			entities.replaceValues(id, newMoments);
		}
	}

	public void collapse(Moment theNext) {
		entities.putAll(theNext.entities);
		blocks.putAll(theNext.blocks);

		for (String id : entities.keySet())
			capEntity(id);
		for (BlockPos pos : blocks.keySet())
			capBlock(pos);
	}

	public void apply(Entity entity) {
		List<EntityMoment> momentsOfEntity = entities.get(entity.getCachedUniqueIdString());
		if (momentsOfEntity == null || momentsOfEntity.isEmpty())
			return;
		momentsOfEntity.get(0).apply(entity);
	}

	public void apply(Entity entity, float partialTicks) {
		if (partialTicks == 0) {
			apply(entity);
			return;
		}

		List<EntityMoment> momentsOfEntity = entities.get(entity.getCachedUniqueIdString());
		if (momentsOfEntity == null || momentsOfEntity.isEmpty())
			return;

		int stackIndexOfMoment = (int) (momentsOfEntity.size() * partialTicks);
		int indexOfMoment = momentsOfEntity.size() - stackIndexOfMoment;
		if (indexOfMoment == 0) {
			apply(entity);
			return;
		}

		EntityMoment momentToApply = momentsOfEntity.get(indexOfMoment);
		EntityMoment nextMoment = momentsOfEntity.get(indexOfMoment - 1);
		float subPartial = partialTicks * momentsOfEntity.size() - ((float) stackIndexOfMoment / momentsOfEntity.size());
		momentToApply.apply(entity, nextMoment, subPartial);
	}

	public void apply(World world, BlockPos pos) {

		List<IBlockState> momentsOfBlock = blocks.get(pos);
		if (momentsOfBlock == null || momentsOfBlock.isEmpty())
			return;

		world.setBlockState(pos, momentsOfBlock.get(0));
	}

	public void apply(World world, BlockPos pos, float partialTicks) {
		if (partialTicks == 0) {
			apply(world, pos);
			return;
		}

		List<IBlockState> momentsOfBlock = blocks.get(pos);
		if (momentsOfBlock == null || momentsOfBlock.isEmpty())
			return;

		int stackIndexOfMoment = (int) (momentsOfBlock.size() * partialTicks);
		int indexOfMoment = momentsOfBlock.size() - stackIndexOfMoment;

		world.setBlockState(pos, momentsOfBlock.get(indexOfMoment));
	}

	public void apply(World world, Collection<Entity> tracked) {
		for (BlockPos position : blocks.keySet())
			apply(world, position);
		for (Entity entity : tracked)
			apply(entity);
	}

	public void apply(World world, Collection<Entity> tracked, float partialTicks) {
		for (BlockPos position : blocks.keySet())
			apply(world, position, partialTicks);
		for (Entity entity : tracked)
			apply(entity, partialTicks);
	}

	public Moment snapshot() {
		for (String id : entities.keySet())
			capEntity(id);
		for (BlockPos pos : blocks.keySet())
			capBlock(pos);

		Moment moment = new Moment();
		moment.totalDifference.putAll(totalDifference);
		moment.entities.putAll(entities);
		moment.blocks.putAll(blocks);
		return moment;
	}

	public NBTTagCompound serializeNBT() {
		for (String id : entities.keySet())
			capEntity(id);
		for (BlockPos pos : blocks.keySet())
			capBlock(pos);

		NBTTagCompound momentSerialized = new NBTTagCompound();
		NBTTagList blocksSerialized = new NBTTagList();
		NBTTagCompound entitiesSerialized = new NBTTagCompound();

		momentSerialized.setTag("blocks", blocksSerialized);
		momentSerialized.setTag("entities", entitiesSerialized);

		for (BlockPos position : blocks.keySet()) {
			NBTTagList states = new NBTTagList();
			NBTTagCompound posCompound = new NBTTagCompound();
			posCompound.setLong("pos", position.toLong());
			posCompound.setTag("states", states);

			for (IBlockState state : blocks.get(position)) {
				ResourceLocation regName = state.getBlock().getRegistryName();
				if (regName != null) {
					NBTTagCompound block = new NBTTagCompound();
					block.setString("id", regName.toString());
					block.setByte("data", (byte) state.getBlock().getMetaFromState(state));
					states.appendTag(block);
				}
			}

			blocksSerialized.appendTag(posCompound);
		}

		for (String identifier : entities.keySet()) {
			NBTTagList moments = new NBTTagList();

			for (EntityMoment moment : entities.get(identifier))
				moments.appendTag(moment.serializeNBT());

			entitiesSerialized.setTag(identifier, moments);
		}

		return momentSerialized;
	}
}

package com.teamwizardry.wizardry.common.core.nemez;

import com.teamwizardry.librarianlib.features.network.PacketHandler;
import com.teamwizardry.wizardry.Wizardry;
import com.teamwizardry.wizardry.common.network.PacketNemezReversal;
import net.minecraft.client.Minecraft;
import net.minecraft.entity.Entity;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import net.minecraftforge.fml.common.network.NetworkRegistry;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

import javax.annotation.Nullable;
import java.lang.ref.WeakReference;
import java.util.HashSet;
import java.util.Objects;

/**
 * Handles time reversal ticking on both client and server
 */
@Mod.EventBusSubscriber(modid = Wizardry.MODID)
public final class NemezEventHandler {

	private static HashSet<Reversal> reversals = new HashSet<>();

	@SideOnly(Side.CLIENT)
	public static NemezTracker getCurrent() {
		if (reversals.isEmpty()) {
			Reversal reversal = new Reversal(Minecraft.getMinecraft().world, new NemezTracker());
			reversals.add(reversal);
		}
		return reversals.iterator().next().nemez;
	}

	public static void reverseTime(World world, NemezTracker tracker, BlockPos locus) {
		Reversal reversal = new Reversal(world, tracker);
		reversal.pos = locus;
		reversals.add(reversal);
	}

	public static void rewind(World world, NemezTracker tracker, BlockPos locus) {
		reverseTime(world, tracker, locus);
		tracker.erase();
	}


	@SubscribeEvent
	public static void worldTick(TickEvent.WorldTickEvent event) {
		if (event.phase == TickEvent.Phase.START)
			reversals.removeIf((reversal) -> {
				if (reversal.world.get() == event.world) {
					if (reversal.nemez.hasNext()) {
						reversal.nemez.applySnapshot(event.world);
						if (reversal.pos != null && reversal.world.get().getTotalWorldTime() % PacketNemezReversal.SYNC_AMOUNT == 0)
							PacketHandler.NETWORK.sendToAllAround(new PacketNemezReversal(reversal.nemez),
									new NetworkRegistry.TargetPoint(reversal.world.get().provider.getDimension(),
											reversal.pos.getX() + 0.5, reversal.pos.getY() + 0.5, reversal.pos.getZ() + 0.5, 96));
					} else {
						for (Entity entity : reversal.nemez.getTrackedEntities(event.world))
							entity.setNoGravity(false);
						return true;
					}
				}
				return reversal.world.get() == null;
			});
	}

	@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void renderTick(TickEvent.RenderTickEvent event) {
		World world = Minecraft.getMinecraft().world;
		if (event.phase == TickEvent.Phase.START) {
			for (Reversal reversal : reversals) {
				if (reversal.world.get() != world) continue;

				if (reversal.nemez.hasNext())
					reversal.nemez.applySnapshot(world, event.renderTickTime);
			}
		}
	}

	private static class Reversal {

		private final WeakReference<World> world;
		private final NemezTracker nemez;

		@Nullable
		private BlockPos pos = null;

		public Reversal(World world, NemezTracker tracker) {
			this.world = new WeakReference<>(world);
			this.nemez = tracker.snapshot();
			this.nemez.collapse();
		}

		@Override
		public boolean equals(Object o) {
			if (this == o) return true;
			if (o == null || getClass() != o.getClass()) return false;
			Reversal reversal = (Reversal) o;
			return Objects.equals(world, reversal.world) &&
					Objects.equals(nemez, reversal.nemez);
		}

		@Override
		public int hashCode() {
			return Objects.hash(world, nemez);
		}
	}
}

package com.teamwizardry.wizardry.common.core.nemez;

import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.Entity;
import net.minecraft.nbt.NBTBase;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.math.BlockPos;
import net.minecraftforge.common.util.INBTSerializable;

import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

/**
 * @author WireSegal
 * Created at 4:19 PM on 1/15/18.
 */
public class NemezManager implements INBTSerializable<NBTTagList> {
	public static final int TIME_COMPRESSION_CONSTANT = 15;
	private final Stack<Moment> moments = new Stack<>();
	private transient Moment currentMoment = new Moment();

	public void pushEntityData(Entity entity) {
		currentMoment.addEntitySnapshot(entity);
	}

	public void pushBlockData(BlockPos pos, IBlockState state) {
		currentMoment.addBlockSnapshot(pos, state);
	}

	public void pushMoment() {
		moments.push(currentMoment);
		currentMoment = new Moment();
	}

	public Moment peekAtMoment() {
		return moments.empty() ? null : moments.peek();
	}

	public Moment popMoment() {
		return moments.pop();
	}

	public void collapse() {
		compress(TIME_COMPRESSION_CONSTANT);
	}

	public boolean needsCompression(int maximumMoments) {
		return moments.size() <= maximumMoments * 1.5;
	}

	public void compressDownTo(int maximumMoments) {
		if (moments.size() <= maximumMoments) return;
		compress((int) Math.ceil((float) maximumMoments / moments.size()));
	}

	public void compress(int factor) {
		List<Moment> collapsedMoments = new ArrayList<>();

		int momentaryIndex = 0;
		Moment lastMoment = null;
		while (moments.size() != 0) {
			Moment currentMoment = moments.pop();
			if (lastMoment == null)
				lastMoment = currentMoment;
			else
				lastMoment.collapse(currentMoment);
			if (++momentaryIndex == factor) {
				collapsedMoments.add(lastMoment);
				momentaryIndex = 0;
				lastMoment = null;
			}
		}
		if (lastMoment != null)
			collapsedMoments.add(lastMoment);

		for (Moment moment : collapsedMoments)
			moments.push(moment);
	}

	public void erase() {
		moments.clear();
		currentMoment = new Moment();
	}

	public NemezManager snapshot() {
		NemezManager manager = new NemezManager();
		for (Moment moment : moments)
			manager.moments.push(moment.snapshot());
		manager.currentMoment = manager.currentMoment.snapshot();
		return manager;
	}

	public NBTTagList serializeFirstN(int n) {
		NBTTagList momentsSerialized = new NBTTagList();
		int i = 0;
		for (Moment moment : moments) {
			momentsSerialized.appendTag(moment.serializeNBT());
			if (i++ == n)
				break;
		}
		return momentsSerialized;
	}

	public void absorb(NBTTagList nbt) {
		Stack<Moment> shifted = new Stack<>();
		for (NBTBase momentUncast : nbt) {
			NBTTagCompound moment = (NBTTagCompound) momentUncast;
			shifted.push(Moment.fromNBT(moment));
		}
		for (Moment moment : moments)
			shifted.push(moment);

		moments.clear();
		for (Moment moment : shifted)
			moments.push(moment);
	}

	@Override
	public NBTTagList serializeNBT() {
		NBTTagList momentsSerialized = new NBTTagList();
		for (Moment moment : moments)
			momentsSerialized.appendTag(moment.serializeNBT());
		return momentsSerialized;
	}

	@Override
	public void deserializeNBT(NBTTagList nbt) {
		moments.clear();
		for (NBTBase momentUncast : nbt) {
			NBTTagCompound moment = (NBTTagCompound) momentUncast;
			moments.push(Moment.fromNBT(moment));
		}
	}
}

package com.teamwizardry.wizardry.common.core.nemez;

import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.Entity;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;
import net.minecraftforge.common.util.INBTSerializable;

import java.util.HashSet;
import java.util.Set;

public class NemezTracker implements INBTSerializable<NBTTagList> {

	public static final int MAXIMUM_MOMENTS = 6000;

	private NemezManager manager = new NemezManager();
	private Set<String> trackingEntities = new HashSet<>();

	public Set<Entity> getTrackedEntities(World world) {
		Set<Entity> tracking = new HashSet<>();
		for (Entity inWorld : world.loadedEntityList)
			if (trackingEntities.contains(inWorld.getCachedUniqueIdString()))
				tracking.add(inWorld);
		return tracking;
	}

	public void trackBlock(BlockPos pos, IBlockState state) {
		manager.pushBlockData(pos, state);
		compressDownTo(MAXIMUM_MOMENTS);
	}

	public void trackEntity(Entity entity) {
		trackingEntities.add(entity.getCachedUniqueIdString());
		manager.pushEntityData(entity);
		compressDownTo(MAXIMUM_MOMENTS);
	}

	public boolean hasNext() {
		return manager.peekAtMoment() != null;
	}

	public void endUpdate() {
		manager.pushMoment();
	}

	public void erase() {
		manager.erase();
	}

	public void collapse() {
		manager.collapse();
	}

	public boolean needsCompression(int maximumMoments) {
		return manager.needsCompression(maximumMoments);
	}

	public void compressDownTo(int maximumMoments) {
		if (needsCompression(maximumMoments))
			manager.compressDownTo(maximumMoments);
	}

	public NemezTracker snapshot() {
		compressDownTo(MAXIMUM_MOMENTS);
		NemezTracker manager = new NemezTracker();
		manager.manager = this.manager.snapshot();
		manager.trackingEntities = new HashSet<>(this.trackingEntities);
		return manager;
	}

	public void applySnapshot(World world) {
		manager.popMoment().apply(world, getTrackedEntities(world));
	}

	public void applySnapshot(World world, float partialTicks) {
		if (partialTicks == 0) {
			applySnapshot(world);
			return;
		}
		manager.peekAtMoment().apply(world, getTrackedEntities(world), partialTicks);
	}

	public NBTTagList nextNMoments(int seconds) {
		return manager.serializeFirstN(seconds);
	}

	public void absorb(NBTTagList data) {
		manager.absorb(data);
	}

	@Override
	public NBTTagList serializeNBT() {
		return manager.serializeNBT();
	}

	@Override
	public void deserializeNBT(NBTTagList nbt) {
		manager.deserializeNBT(nbt);
	}
}

package com.teamwizardry.wizardry.common.entity;

import com.teamwizardry.librarianlib.features.base.entity.EntityMod;
import com.teamwizardry.librarianlib.features.helpers.NBTHelper;
import com.teamwizardry.wizardry.api.item.halo.HaloInfusionItem;
import com.teamwizardry.wizardry.api.item.halo.HaloInfusionItemRegistry;
import com.teamwizardry.wizardry.common.tile.TileHaloInfuser;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.nbt.NBTTagString;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.EnumHand;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;

import javax.annotation.Nonnull;

/**
 * Created by Demoniaque on 8/21/2016.
 */
public class EntityHaloInfusionItem extends EntityMod {

	private BlockPos infuserPos;
	private int slot;
	@Nonnull
	private HaloInfusionItem haloInfusionItem = HaloInfusionItemRegistry.EMPTY;

	public EntityHaloInfusionItem(World worldIn) {
		super(worldIn);
		setSize(1F, 1F);
		isAirBorne = true;
	}

	public EntityHaloInfusionItem(World worldIn, @Nonnull HaloInfusionItem item, BlockPos infuserPos, int slot) {
		super(worldIn);
		this.infuserPos = infuserPos;
		this.slot = slot;
		setSize(1F, 1F);
		haloInfusionItem = item;
		isAirBorne = true;
	}

	@Override
	protected void entityInit() {

	}

	@Override
	public void onUpdate() {
		super.onUpdate();
		if (world == null || infuserPos == null) return;

		TileEntity tile = world.getTileEntity(infuserPos);
		if (!(tile instanceof TileHaloInfuser)) {
			world.removeEntity(this);
		}
	}

	@Override
	public boolean canBeCollidedWith() {
		if (world == null || infuserPos == null) return false;

		TileEntity tile = world.getTileEntity(infuserPos);
		return tile instanceof TileHaloInfuser && !((TileHaloInfuser) tile).getHalo().isEmpty();
	}

	@Override
	public boolean processInitialInteract(EntityPlayer player, EnumHand hand) {
		TileEntity tile = world.getTileEntity(infuserPos);
		if (!(tile instanceof TileHaloInfuser)) {
			world.removeEntity(this);
			return false;
		}

		ItemStack heldItem = player.getHeldItem(hand);
		if (heldItem.isEmpty()) {
			ItemStack slotted = getHaloInfusionItem().getStack();
			if (!slotted.isEmpty()) {
				player.setHeldItem(hand, slotted);
				setHaloInfusionItem(HaloInfusionItemRegistry.EMPTY, false);
				return true;
			} else return true;
		}

		for (HaloInfusionItem haloInfusionItem : HaloInfusionItemRegistry.getItems()) {
			if (haloInfusionItem.getStack().isItemEqual(heldItem)) {
				setHaloInfusionItem(haloInfusionItem, false);

				// todo: remove from hand
				return true;
			}
		}

		return true;
	}

	@Override
	public void readCustomNBT(NBTTagCompound compound) {
		super.readCustomNBT(compound);
		haloInfusionItem = HaloInfusionItem.deserialize(compound.getString("halo_infusion_item"));
		infuserPos = BlockPos.fromLong(compound.getLong("infuser_pos"));
		slot = compound.getInteger("slot");

		setHaloInfusionItem(haloInfusionItem, true);
	}

	@Override
	public void writeCustomNBT(NBTTagCompound compound) {
		super.writeCustomNBT(compound);
		compound.setString("halo_infusion_item", haloInfusionItem.getNbtName());
		compound.setLong("infuser_pos", infuserPos.toLong());
		compound.setInteger("slot", slot);
	}

	public BlockPos getInfuserPos() {
		return infuserPos;
	}

	@Nonnull
	public HaloInfusionItem getHaloInfusionItem() {
		return haloInfusionItem;
	}

	public void setHaloInfusionItem(@Nonnull HaloInfusionItem haloInfusionItem, boolean soft) {
		this.haloInfusionItem = haloInfusionItem;

		if (soft) return;

		TileEntity tile = world.getTileEntity(infuserPos);
		if (tile instanceof TileHaloInfuser) {
			TileHaloInfuser haloInfuser = (TileHaloInfuser) tile;
			ItemStack halo = haloInfuser.getHalo();

			NBTTagList slots = NBTHelper.getList(halo, "slots", NBTTagString.class);
			if (slots == null || slots.tagCount() < HaloInfusionItemRegistry.getItems().size() - 1) {
				slots = new NBTTagList();

				for (int i = 0; i < HaloInfusionItemRegistry.getItems().size(); i++) {
					slots.appendTag(new NBTTagString(HaloInfusionItemRegistry.EMPTY.getNbtName()));
				}
			}

			slots.set(slot, new NBTTagString(haloInfusionItem.getNbtName()));

			NBTHelper.setList(halo, "slots", slots);
		}
	}
}

